/**
 * Orders an expert review queue.
 * Uncertain rows come first. Key rows follow: spend-based activity,
 * maintenance and refrigerant, and the largest calculated kilograms.
 * Rows waiting on the company stay in their own stage so they do not
 * block the rows the expert can decide now.
 */

const STAGE_ORDER = Object.freeze(['uncertain', 'key', 'waiting', 'calculated', 'approved']);

const STAGE_COPY = Object.freeze({
  uncertain: {
    title: 'Uncertain transactions',
    instruction: 'Review these first. The kilogram is missing, held for a named activity, or the company has replied and that reply still needs a decision.'
  },
  key: {
    title: 'Key transactions',
    instruction: 'Review these next. Spend-based rows, maintenance and refrigerant, and the largest calculated kilograms are in this stage.'
  },
  waiting: {
    title: 'Waiting for the company',
    instruction: 'An information request is still open. Continue with the other stages, then return when the company replies.'
  },
  calculated: {
    title: 'Remaining calculated transactions',
    instruction: 'These already use a measured quantity and a stored factor. Confirm them after the uncertain and key rows.'
  },
  approved: {
    title: 'Approved in this session',
    instruction: 'These rows already have a decision. They stay here so the open stages stay at the top.'
  }
});

const UNCERTAIN_REASONS = new Set([
  'missing_activity',
  'missing_quantity_or_unit',
  'missing_fuel_or_material',
  'bill_required',
  'calculation_failed'
]);

const rowId = (row = {}) => String(row._id || row.id || '');

const readFields = (row = {}) => {
  const footprint = row.carbonFootprint || {};
  const lineage = footprint.factorLineage || {};
  const record = footprint.calculationRecord || {};
  return {
    formula: String(row.formula || record.formula || ''),
    factorId: String(row.factorId || lineage.id || ''),
    method: String(row.quantificationMethod || footprint.quantificationMethod || '').toLowerCase(),
    kilograms: Number(row.co2Emissions != null ? row.co2Emissions : footprint.co2Emissions) || 0,
    quantity: Number(row.quantity != null ? row.quantity : row.metadata?.quantity),
    calculationClass: String(row.calculationClass || '')
  };
};

const byDescription = (left, right) => String(left.description || '').localeCompare(String(right.description || ''));

const byKilograms = (left, right) => {
  const gap = readFields(right).kilograms - readFields(left).kilograms;
  return gap || byDescription(left, right);
};

const needsNamedActivity = (row) => {
  const fields = readFields(row);
  return fields.method.includes('admin_emission_review')
    || fields.formula === 'adminEmissionReview'
    || fields.factorId === 'activity_classification_required';
};

const isMaintenanceOrRefrigerant = (row = {}) => {
  const text = `${row.category || ''} ${row.subcategory || ''} ${row.recommendation?.id || ''}`.toLowerCase();
  return row.category === 'maintenance' || /refrigerant|maintenance/.test(text);
};

const isSpendBased = (row = {}) => {
  const fields = readFields(row);
  return fields.calculationClass === 'spend_based'
    || fields.method.includes('spend')
    || fields.formula.includes('spendAmount');
};

const isUncertain = (row = {}) => {
  if (row.informationRequest?.status === 'answered') return true;
  const fields = readFields(row);
  if (fields.calculationClass === 'spend_based') return false;
  if (fields.calculationClass === 'calculated' && fields.kilograms > 0) return false;
  if (fields.calculationClass === 'without_calculation') return true;
  if (needsNamedActivity(row)) return true;
  if (row.recommendation && row.recommendation.available === false) return true;
  if (UNCERTAIN_REASONS.has(row.resolution?.reason || '')) return true;
  if (!(fields.kilograms > 0)) return true;
  return false;
};

const uncertainSort = (left, right) => {
  const rank = (row) => {
    if (row.informationRequest?.status === 'answered') return 0;
    if (needsNamedActivity(row)) return 1;
    return 2;
  };
  return rank(left) - rank(right) || byDescription(left, right);
};

const planExpertReview = (rows = []) => {
  const list = Array.isArray(rows) ? rows : [];
  const waiting = [];
  const uncertain = [];
  const rest = [];
  const approved = [];

  list.forEach((row) => {
    if (row?.settled) approved.push(row);
    else if (row?.informationRequest?.status === 'open') waiting.push(row);
    else if (isUncertain(row)) uncertain.push(row);
    else rest.push(row);
  });

  uncertain.sort(uncertainSort);
  waiting.sort(byDescription);
  approved.sort(byDescription);

  const largeIds = new Set();
  const measured = rest.filter((row) => !isSpendBased(row) && !isMaintenanceOrRefrigerant(row) && readFields(row).kilograms > 0);
  const measuredTotal = measured.reduce((sum, row) => sum + readFields(row).kilograms, 0);
  measured.forEach((row) => {
    if (measuredTotal > 0 && readFields(row).kilograms / measuredTotal >= 0.1) largeIds.add(rowId(row));
  });
  if (largeIds.size === 0 && measured.length > 0) {
    const largest = measured.slice().sort(byKilograms)[0];
    largeIds.add(rowId(largest));
  }

  const key = [];
  const calculated = [];
  rest.forEach((row) => {
    if (isSpendBased(row) || isMaintenanceOrRefrigerant(row) || largeIds.has(rowId(row))) key.push(row);
    else calculated.push(row);
  });
  key.sort(byKilograms);
  calculated.sort(byKilograms);

  const grouped = {
    uncertain,
    key,
    waiting,
    calculated,
    approved
  };

  const transactions = [];
  const stages = STAGE_ORDER.map((id) => {
    const copy = STAGE_COPY[id];
    const stageRows = grouped[id];
    const transactionIds = [];
    stageRows.forEach((row) => {
      const reviewOrder = transactions.length + 1;
      transactions.push({
        ...row,
        reviewStage: id,
        reviewOrder
      });
      transactionIds.push(rowId(row));
    });
    return {
      id,
      title: copy.title,
      instruction: copy.instruction,
      count: stageRows.length,
      open: stageRows.filter((row) => !row.settled).length,
      transactionIds
    };
  }).filter((stage) => stage.count > 0);

  return { transactions, stages };
};

export {
  STAGE_COPY,
  STAGE_ORDER,
  planExpertReview
};
