import React from 'react';
import { Box, MenuItem, TextField, Typography } from '@mui/material';
import { scope3LinkGuidance } from '../../shared/consultantScope3Boundary';

const OPTIONS = [8, 10, 11, 12, 13, 14, 15] as const;

export const scope3CategoryPayload = (value?: string) => {
  const number = Number(value);
  return (OPTIONS as readonly number[]).includes(number) ? number : undefined;
};

const GuidanceList = ({ title, lines }: { title: string; lines: string[] }) => (
  <Box>
    <Typography variant="subtitle2">{title}</Typography>
    {lines.map((line) => (
      <Typography key={line} variant="body2" color="text.secondary">{line}</Typography>
    ))}
  </Box>
);

const ExpertScope3LinkFields: React.FC<{
  value: string;
  onChange: (next: string) => void;
}> = ({ value, onChange }) => {
  const guidance = scope3CategoryPayload(value) ? scope3LinkGuidance(Number(value)) : null;
  return (
    <Box sx={{ display: 'grid', gap: 1 }}>
      <TextField
        select
        size="small"
        label="Link Scope 3 category"
        value={value}
        onChange={(event) => onChange(event.target.value)}
      >
        <MenuItem value="">Leave as calculated</MenuItem>
        {OPTIONS.map((item) => {
          const detail = scope3LinkGuidance(item);
          return (
            <MenuItem key={item} value={String(item)}>
              {detail ? `${item} ${detail.short}` : String(item)}
            </MenuItem>
          );
        })}
      </TextField>
      {guidance ? (
        <Box data-testid="scope3-link-guidance" sx={{ display: 'grid', gap: 1 }}>
          <Typography variant="body2">
            {`Saving this link reports the Scope 3 kilograms in ${guidance.label}. Scope 1 and Scope 2 stay as calculated. Use ${guidance.unit} unless the bill names another activity unit.`}
          </Typography>
          <GuidanceList title="Update the voucher" lines={guidance.transaction} />
          <GuidanceList title="Update the company profile" lines={guidance.profile} />
          <GuidanceList title="Update the rest of the record" lines={guidance.other} />
        </Box>
      ) : null}
    </Box>
  );
};

export default ExpertScope3LinkFields;
