import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Paper,
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableRow,
  TextField,
  Typography,
} from '@mui/material';
import axios from 'axios';
import { buildApiUrl } from '../../config/apiConfig';
import { ConsultantUserSelection } from './ExpertCalculationReview';
import { downloadUncertainWorkbook } from './downloadUncertainWorkbook';

export interface ConsultantUserRow extends ConsultantUserSelection {
  role: string;
  openRequired: number;
  ready: boolean;
  counts: {
    withoutCalculation: number;
    spendBased: number;
    calculated: number;
  };
}

const ExpertUserList: React.FC<{
  onSelect: (user: ConsultantUserRow) => void;
}> = ({ onSelect }) => {
  const [users, setUsers] = useState<ConsultantUserRow[]>([]);
  const [query, setQuery] = useState('');
  const [appliedQuery, setAppliedQuery] = useState('');
  const [cursor, setCursor] = useState<string | null>(null);
  const [totalsScope, setTotalsScope] = useState<'loaded_page' | 'complete'>('loaded_page');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [downloadingId, setDownloadingId] = useState<string | null>(null);

  const load = useCallback(async (append: boolean, nextCursor?: string | null, search = appliedQuery) => {
    setLoading(true);
    setError(null);
    try {
      const response = await axios.get(buildApiUrl('/expert/users'), {
        headers: { Authorization: `Bearer ${localStorage.getItem('token')}` },
        params: { limit: 25, q: search || undefined, cursor: nextCursor || undefined },
      });
      const page: ConsultantUserRow[] = response.data?.data?.users || [];
      setUsers((current) => {
        if (!append) return page;
        const seen = new Set(current.map((user) => `${user.userId}-${user.msmeId || 'none'}`));
        return [...current, ...page.filter((user) => !seen.has(`${user.userId}-${user.msmeId || 'none'}`))];
      });
      setCursor(response.data?.data?.nextCursor || null);
      setTotalsScope(response.data?.data?.totalsScope === 'complete' ? 'complete' : 'loaded_page');
    } catch (loadError: any) {
      setError(loadError?.response?.data?.message || 'Failed to load users.');
    } finally {
      setLoading(false);
    }
  }, [appliedQuery]);

  useEffect(() => {
    void load(false);
  }, [load]);

  const downloadRows = async (user: ConsultantUserRow) => {
    if (!user.msmeId) return;
    setDownloadingId(user.msmeId);
    setError(null);
    try {
      await downloadUncertainWorkbook(user.msmeId);
    } catch (downloadError: any) {
      setError(downloadError?.response?.data?.message || 'The uncertain transactions workbook could not be downloaded.');
    } finally {
      setDownloadingId(null);
    }
  };

  const visible = users;

  return (
    <Paper sx={{ p: 2, mb: 3 }}>
      <Typography variant="h6" component="h2" sx={{ fontWeight: 700, mb: 0.5 }}>
        Company users
      </Typography>
      <Typography variant="body2" color="text.secondary" sx={{ mb: 2 }}>
        Open a company to review its uncertain transactions. The step-by-step review is the default when you continue.
        {totalsScope === 'complete'
          ? ' Counts cover every company that matched this search.'
          : ' Counts cover the companies loaded so far, not every company.'}
      </Typography>
      {error ? (
        <Alert
          severity="error"
          sx={{ mb: 2 }}
          action={<Button color="inherit" size="small" onClick={() => void load(false)}>Retry</Button>}
        >
          {error}
        </Alert>
      ) : null}
      <Box sx={{ display: 'flex', gap: 1, mb: 2, flexWrap: 'wrap' }}>
        <TextField
          size="small"
          label="Find a user"
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          onKeyDown={(event) => {
            if (event.key === 'Enter') {
              setAppliedQuery(query.trim());
            }
          }}
          sx={{ maxWidth: 360 }}
        />
        <Button size="small" variant="outlined" onClick={() => setAppliedQuery(query.trim())}>Search</Button>
      </Box>
      {loading ? <Typography variant="body2">Loading users…</Typography> : null}
      {!loading && users.length === 0 ? (
        <Typography variant="body2">
          {appliedQuery ? 'No users match this search.' : 'No users are available for consultant review.'}
        </Typography>
      ) : null}
      {visible.length > 0 ? (
        <Box sx={{ overflowX: 'auto' }}>
          <Table size="small">
            <TableHead>
              <TableRow>
                <TableCell>User</TableCell>
                <TableCell>Company</TableCell>
                <TableCell align="right">Uncertain transactions</TableCell>
                <TableCell>Report</TableCell>
                <TableCell />
              </TableRow>
            </TableHead>
            <TableBody>
              {visible.map((user) => (
                <TableRow key={`${user.userId}-${user.msmeId || 'none'}`}>
                  <TableCell>
                    <Typography variant="body2" sx={{ fontWeight: 600 }}>{user.name}</Typography>
                    <Typography variant="caption" color="text.secondary">{user.email}</Typography>
                  </TableCell>
                  <TableCell>{user.companyName || 'No company ledger'}</TableCell>
                  <TableCell align="right">
                    {user.msmeId
                      ? `${user.openRequired} open · ${user.counts.withoutCalculation} without calculation · ${user.counts.spendBased} spend-based`
                      : '—'}
                  </TableCell>
                  <TableCell>
                    {!user.msmeId ? 'No ledger' : (user.ready ? 'Can generate' : 'Waiting for approval')}
                  </TableCell>
                  <TableCell>
                    <Box sx={{ display: 'flex', gap: 1, flexWrap: 'wrap' }}>
                      <Button
                        size="small"
                        variant="outlined"
                        disabled={!user.msmeId || downloadingId === user.msmeId}
                        onClick={() => { void downloadRows(user); }}
                      >
                        {downloadingId === user.msmeId ? 'Downloading' : 'Download uncertain rows'}
                      </Button>
                      <Button
                        size="small"
                        variant="contained"
                        disabled={!user.msmeId}
                        onClick={() => onSelect(user)}
                      >
                        {`Review ${user.name}`}
                      </Button>
                    </Box>
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </Box>
      ) : null}
      {cursor ? (
        <Button sx={{ mt: 2 }} onClick={() => void load(true, cursor)} disabled={loading}>Load more companies</Button>
      ) : null}
    </Paper>
  );
};

export default ExpertUserList;
